import { GoogleGenAI, Type } from "@google/genai";
import type { GeneratedData, PromptCard } from '../types';

// A placeholder image to use when generation fails
const FAILED_IMAGE_PLACEHOLDER = 'data:image/svg+xml;base64,';

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    archetype: { type: Type.STRING, description: "A single, powerful archetype that captures the theme (e.g., Warlord, Scholar, Rogue)." },
    tone: { type: Type.STRING, description: "Two or three descriptive words for the tone (e.g., Gothic, Dramatic)." },
    use: { type: Type.STRING, description: "The intended use case for these images (e.g., Cinematic Image Generation)." },
    cards: {
      type: Type.ARRAY,
      description: "An array of exactly 5 unique 'Prompt Card' objects.",
      items: {
        type: Type.OBJECT,
        properties: {
          glyph: { type: Type.STRING, description: "A single, relevant emoji." },
          title: { type: Type.STRING, description: "A short, evocative title for the card." },
          prompt: { type: Type.STRING, description: "A multi-line string with 7 lines detailing Subject, Lens, Lighting, Style, Color, Composition, and Constraints." },
          caption: { type: Type.STRING, description: "A brief, descriptive caption for the image generated from the prompt." },
          tags: { 
            type: Type.ARRAY, 
            description: "An array of 2-4 single-word lowercase tags for filtering.",
            items: { type: Type.STRING }
          },
        },
        required: ["glyph", "title", "prompt", "caption", "tags"],
      },
    },
    negativePrompts: {
      type: Type.ARRAY,
      description: "An array of 5 short strings for a 'Negative Prompt Overlay'.",
      items: { type: Type.STRING },
    },
    remixSuggestions: {
      type: Type.ARRAY,
      description: "An array of 3 creative suggestions for 'Remix Rituals'.",
      items: { type: Type.STRING },
    },
  },
  required: ["archetype", "tone", "use", "cards", "negativePrompts", "remixSuggestions"],
};

export const generatePromptSet = async (idea: string): Promise<Omit<GeneratedData, 'mainTitle' | 'logoImageUrl' | 'bannerImageUrl' | 'cards'> & { cards: Omit<PromptCard, 'imageUrl'>[] }> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
You are a creative director specializing in dark fantasy world-building. Your task is to generate a "Relic Series" prompt card set based on a user-provided theme.
The theme is: "${idea}"
Ensure the output adheres to the specified JSON schema and uses high-end vocabulary.
`;

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-lite-latest',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: responseSchema,
        }
    });

    return JSON.parse(response.text.trim());
};

export const generateImage = async (
    prompt: string, 
    aspectRatio: '1:1' | '16:9' | '4:3' | '9:16' | '3:4' = '16:9',
    imageSize: '1K' | '2K' | '4K' = '1K'
): Promise<string> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: {
                parts: [{ text: `High-fidelity cinematic dark fantasy masterpiece: ${prompt}` }],
            },
            config: {
                imageConfig: {
                    aspectRatio: aspectRatio,
                    imageSize: imageSize
                },
                tools: [{ googleSearch: {} }] // Pro image supports search for better context
            },
        });

        const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
        if (part?.inlineData?.data) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }

        console.warn("No image data found in response for:", prompt);
        return FAILED_IMAGE_PLACEHOLDER;
    } catch (error: any) {
        if (error?.message?.includes("Requested entity was not found")) {
            // Signal to UI that key selection might be needed again
            throw new Error("API_KEY_RESET_REQUIRED");
        }
        console.error("Error during image generation:", error);
        return FAILED_IMAGE_PLACEHOLDER;
    }
}

import React, { useState, useCallback, useEffect } from 'react';
import { GeneratorForm } from './components/GeneratorForm';
import { LoadingScreen } from './components/LoadingScreen';
import { PromptCardSet } from './components/PromptCardSet';
import * as geminiService from './services/geminiService';
import type { GeneratedData } from './types';

// Extend window for AI Studio helpers
declare global {
    interface Window {
        aistudio: {
            hasSelectedApiKey: () => Promise<boolean>;
            openSelectKey: () => Promise<void>;
        };
    }
}

const App: React.FC = () => {
    const [userInput, setUserInput] = useState<string>('');
    const [generatedData, setGeneratedData] = useState<GeneratedData | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const [needsKey, setNeedsKey] = useState(false);

    // Configurable generation options
    const [imageSize, setImageSize] = useState<'1K' | '2K' | '4K'>('1K');
    const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '4:3'>('16:9');

    useEffect(() => {
        const checkKey = async () => {
            if (window.aistudio) {
                const hasKey = await window.aistudio.hasSelectedApiKey();
                setNeedsKey(!hasKey);
            }
        };
        checkKey();
    }, []);

    const handleSelectKey = async () => {
        if (window.aistudio) {
            await window.aistudio.openSelectKey();
            setNeedsKey(false);
        }
    };

    const handleGenerate = useCallback(async (idea: string) => {
        setIsLoading(true);
        setError(null);
        setGeneratedData(null);
        setUserInput(idea);

        try {
            setLoadingMessage('Initializing Nano Banana Pro Engine...');
            const textData = await geminiService.generatePromptSet(idea);

            setLoadingMessage('Optimizing Cinematic Vectors...');

            const imagePrompts = [
                { type: 'banner', prompt: `Wide shot, dark fantasy landscape, ${textData.tone}, highly detailed, volumetric lighting.`, aspectRatio: aspectRatio },
                ...textData.cards.map((card, index) => ({
                    type: `card-${index}`,
                    prompt: `${card.title}, ${card.prompt.replace(/\n/g, ', ')}, high resolution dark fantasy art`,
                    aspectRatio: aspectRatio
                }))
            ];

            const imageUrls: { [key:string]: string } = {};

            for (let i = 0; i < imagePrompts.length; i++) {
                const p = imagePrompts[i];
                setLoadingMessage(`Manifesting Relic ${i + 1}/${imagePrompts.length} (${imageSize} Resolution)...`);
                try {
                    const imageUrl = await geminiService.generateImage(p.prompt, p.aspectRatio, imageSize);
                    imageUrls[p.type] = imageUrl;
                } catch (e: any) {
                    if (e.message === "API_KEY_RESET_REQUIRED") {
                        setNeedsKey(true);
                        throw new Error("Please select a valid paid API key for Pro features.");
                    }
                    throw e;
                }
            }

            const finalData: GeneratedData = {
                ...textData,
                mainTitle: 'Demon Codex Pro',
                bannerImageUrl: imageUrls['banner'],
                cards: textData.cards.map((card, index) => ({
                    ...card,
                    imageUrl: imageUrls[`card-${index}`] || '',
                })),
            };

            setGeneratedData(finalData);

        } catch (err) {
            console.error(err);
            const errorMessage = err instanceof Error ? err.message : 'Ancient engine failure.';
            setError(errorMessage);
        } finally {
            setIsLoading(false);
            setLoadingMessage('');
        }
    }, [imageSize, aspectRatio]);

    const handleStartOver = () => {
        setGeneratedData(null);
        setError(null);
        setUserInput('');
    }

    if (needsKey) {
        return (
            <div className="min-h-screen bg-[#0b0b0f] flex items-center justify-center p-6 text-center">
                <div className="max-w-md p-8 rounded-2xl bg-[#111318] border border-[#8d1a1a]/30 shadow-2xl">
                    <div className="text-4xl mb-4">💎</div>
                    <h2 className="text-2xl font-bold mb-4 text-[#e8e6e3]">Pro Access Required</h2>
                    <p className="text-[#9aa0a6] mb-8">
                        This application uses <span className="text-[#f5a16f]">Gemini 3 Pro Image</span>. 
                        A paid API key with billing enabled is required for high-resolution generation.
                    </p>
                    <button 
                        onClick={handleSelectKey}
                        className="w-full bg-gradient-to-r from-[#8d1a1a] to-[#c26b3a] text-white font-bold py-3 rounded-xl hover:opacity-90 transition-all"
                    >
                        Select API Key
                    </button>
                    <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="block mt-4 text-xs text-[#70757e] hover:text-[#f5a16f]">
                        Learn about billing setup →
                    </a>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-[#0b0b0f] text-[#e8e6e3] font-['Inter'] min-h-screen w-full selection:bg-[#8d1a1a] selection:text-white">
            <main className="max-w-[1100px] mx-auto p-4 md:p-5">
                {isLoading && <LoadingScreen message={loadingMessage} />}

                {!isLoading && !generatedData && (
                     <div className="flex flex-col items-center justify-center min-h-[80vh] py-12">
                        <div className="text-center mb-10 animate-fade-in">
                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#8d1a1a]/20 border border-[#8d1a1a]/30 text-[#f5a16f] text-xs font-bold tracking-widest uppercase mb-4">
                                <span className="w-2 h-2 rounded-full bg-[#f5a16f] animate-pulse"></span>
                                Nano Banana Pro Powered
                            </div>
                            <h1 className="text-6xl md:text-9xl font-extrabold tracking-tighter text-transparent bg-clip-text bg-gradient-to-br from-[#f5a16f] via-[#f0d7c2] to-[#b14a38]" style={{filter: 'drop-shadow(0 0 15px rgba(141, 26, 26, 0.4))'}}>
                                DEMON CODEX
                            </h1>
                            <p className="text-xl text-[#9aa0a6] mt-6 max-w-lg mx-auto leading-relaxed">
                                The ultimate Relic generator for professional dark fantasy worldbuilders and cinematic artists.
                            </p>
                        </div>

                        <GeneratorForm
                            initialValue={userInput}
                            onGenerate={handleGenerate}
                            isGenerating={isLoading}
                            imageSize={imageSize}
                            setImageSize={setImageSize}
                            aspectRatio={aspectRatio}
                            setAspectRatio={setAspectRatio}
                        />

                         {error && (
                            <div className="mt-8 p-5 bg-[#8d1a1a]/10 border border-[#8d1a1a]/40 text-[#f0d7c2] rounded-xl max-w-xl text-center backdrop-blur-md">
                                <p className="font-bold flex items-center justify-center gap-2"><span className="text-xl">⚠️</span> Forge Interrupted</p>
                                <p className="text-sm mt-1 opacity-80">{error}</p>
                            </div>
                        )}

                        <div className="mt-16 grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl border-t border-[#242830] pt-12">
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830]">
                                <h3 className="text-white font-bold mb-2">Pro Engine</h3>
                                <p className="text-xs text-[#70757e]">Using Gemini 3 Pro Image for 4K textures and advanced spatial logic.</p>
                            </div>
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830]">
                                <h3 className="text-white font-bold mb-2">Flash-Lite v2.5</h3>
                                <p className="text-xs text-[#70757e]">Sub-second intelligence for prompt engineering and metadata generation.</p>
                            </div>
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830]">
                                <h3 className="text-white font-bold mb-2">Grounding</h3>
                                <p className="text-xs text-[#70757e]">Real-time visual search integration for historically accurate dark fantasy tropes.</p>
                            </div>
                        </div>
                    </div>
                )}

                {generatedData && (
                    <PromptCardSet data={generatedData} onStartOver={handleStartOver} />
                )}
            </main>
        </div>
    );
};

export default App;

import React, { useState } from 'react';

interface GeneratorFormProps {
    initialValue: string;
    onGenerate: (idea: string) => void;
    isGenerating: boolean;
    imageSize: '1K' | '2K' | '4K';
    setImageSize: (size: '1K' | '2K' | '4K') => void;
    aspectRatio: '1:1' | '16:9' | '4:3';
    setAspectRatio: (ratio: '1:1' | '16:9' | '4:3') => void;
}

const examples = [
    { label: 'Shattered Citadel', theme: 'Floating gothic cathedral pieces suspended in a vortex of red clouds' },
    { label: 'Eldritch Knight', theme: 'Heavy obsidian armor leaking cosmic smoke, standing in a field of glass flowers' },
    { label: 'The Sunken Altar', theme: 'Underwater marble altar glowing with bioluminescent tentacles' },
    { label: 'Ash Wasteland', theme: 'Infinite grey dunes with massive skeletal ribcages emerging from sand' },
];

export const GeneratorForm: React.FC<GeneratorFormProps> = ({ 
    initialValue, onGenerate, isGenerating, 
    imageSize, setImageSize, aspectRatio, setAspectRatio 
}) => {
    const [idea, setIdea] = useState(initialValue);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (idea.trim() && !isGenerating) {
            onGenerate(idea.trim());
        }
    };

    return (
        <form onSubmit={handleSubmit} className="w-full max-w-3xl flex flex-col items-center gap-8">
            <div className="w-full flex flex-col gap-6">
                <textarea
                    value={idea}
                    onChange={(e) => setIdea(e.target.value)}
                    placeholder="Whisper your dark fantasy concept..."
                    className="w-full p-6 rounded-2xl border border-[#242830] focus:border-[#c26b3a] focus:ring-4 focus:ring-[#c26b3a]/10 transition-all bg-[#111318] shadow-2xl text-xl text-[#e8e6e3] placeholder:text-[#70757e] min-h-[140px]"
                    disabled={isGenerating}
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex flex-col gap-2">
                        <label className="text-xs font-bold text-[#70757e] uppercase tracking-widest ml-1">Render Quality</label>
                        <div className="flex bg-[#111318] p-1 rounded-xl border border-[#242830]">
                            {(['1K', '2K', '4K'] as const).map((size) => (
                                <button
                                    key={size}
                                    type="button"
                                    onClick={() => setImageSize(size)}
                                    className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                                        imageSize === size 
                                        ? 'bg-[#c26b3a] text-white shadow-lg' 
                                        : 'text-[#70757e] hover:text-white'
                                    }`}
                                >
                                    {size} {size === '4K' && '💎'}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        <label className="text-xs font-bold text-[#70757e] uppercase tracking-widest ml-1">Composition</label>
                        <div className="flex bg-[#111318] p-1 rounded-xl border border-[#242830]">
                            {(['1:1', '16:9', '4:3'] as const).map((ratio) => (
                                <button
                                    key={ratio}
                                    type="button"
                                    onClick={() => setAspectRatio(ratio)}
                                    className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                                        aspectRatio === ratio 
                                        ? 'bg-[#c26b3a] text-white shadow-lg' 
                                        : 'text-[#70757e] hover:text-white'
                                    }`}
                                >
                                    {ratio}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <div className="w-full">
                <div className="flex flex-wrap justify-center gap-3">
                    {examples.map(ex => (
                        <button 
                            key={ex.label}
                            type="button" 
                            onClick={() => !isGenerating && setIdea(ex.theme)} 
                            disabled={isGenerating}
                            className="bg-[#1b1f27]/50 border border-[#242830] rounded-full px-5 py-2 text-sm text-[#dcd8d3] hover:border-[#c26b3a] transition-all hover:scale-105 active:scale-95 disabled:opacity-50"
                        >
                            {ex.label}
                        </button>
                    ))}
                </div>
            </div>

            <button
                type="submit"
                disabled={isGenerating || !idea.trim()}
                className="group relative w-full md:w-auto overflow-hidden bg-gradient-to-r from-[#8d1a1a] to-[#c26b3a] text-white font-black text-xl py-5 px-16 rounded-2xl hover:opacity-90 transition-all duration-500 shadow-[0_0_30px_rgba(141,26,26,0.5)] active:scale-95 disabled:grayscale"
            >
