        model: 'gemini-3-pro-preview',
        contents: `Analyze this dark fantasy relic and write a 2-sentence mysterious lore snippet for it. 
        Title: ${card.title}
        Description: ${card.caption}`,
      });
      setLore(response.text || "The lore remains hidden in shadows.");
    } catch (err) {
      console.error(err);
      setLore("The ancient scrolls are unreadable.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <article className="card bg-[#111318] border border-[#242830] rounded-xl overflow-hidden flex flex-col print:border-gray-300">
