        <div className="flex justify-between items-start">
            <h3 className="title-sm font-bold text-lg text-[#e8e6e3]">{card.title}</h3>
            <button 
                onClick={analyzeRelic} 
                disabled={isAnalyzing}
                title="Deep Intelligence Analysis"
                className="text-xs text-[#f5a16f] hover:text-[#c26b3a] transition-colors disabled:opacity-50"
            >
                {isAnalyzing ? 'Analyzing...' : '✧ Extract Lore'}
