        <div className="meta flex gap-2 flex-wrap">
          <span className="chip bg-[#1b1f27] border border-[#242830] rounded-full px-3 py-1 text-xs text-[#dcd8d3]">{archetype}</span>
          {card.tags.map(tag => <span key={tag} className="chip bg-[#1b1f27] border border-[#242830] rounded-full px-3 py-1 text-xs text-[#dcd8d3]">#{tag}</span>)}
        </div>

        <div className="actions flex gap-2 flex-wrap mt-2 no-print">
          <button onClick={() => setShowPrompt(!showPrompt)} className="btn flex-1 secondary bg-transparent border border-[#242830] text-[#e8e6e3] px-4 py-2 rounded-lg text-sm font-semibold hover:bg-[#242830] transition-colors">
            {showPrompt ? 'Hide Logic' : 'View Logic'}
