            const imagePrompts = [
                { type: 'banner', prompt: `Wide shot, dark fantasy landscape, ${textData.tone}, highly detailed, volumetric lighting.`, aspectRatio: aspectRatio },
                ...textData.cards.map((card, index) => ({
                    type: `card-${index}`,
                    prompt: `${card.title}, ${card.prompt.replace(/\n/g, ', ')}, high resolution dark fantasy art`,
                    aspectRatio: aspectRatio
                }))
            ];

            const imageUrls: { [key:string]: string } = {};

            for (let i = 0; i < imagePrompts.length; i++) {
                const p = imagePrompts[i];
                setLoadingMessage(`Manifesting Relic ${i + 1}/${imagePrompts.length} (${imageSize} Resolution)...`);
                try {
                    const imageUrl = await geminiService.generateImage(p.prompt, p.aspectRatio, imageSize);
                    imageUrls[p.type] = imageUrl;
                } catch (e: any) {
                    if (e.message === "API_KEY_RESET_REQUIRED") {
                        setNeedsKey(true);
                        throw new Error("Please select a valid paid API key for Pro features.");
                    }
                    throw e;
                }
            }

            const finalData: GeneratedData = {
                ...textData,
                mainTitle: 'Demon Codex Pro',
                bannerImageUrl: imageUrls['banner'],
                cards: textData.cards.map((card, index) => ({
                    ...card,
                    imageUrl: imageUrls[`card-${index}`] || '',
                })),
            };

            setGeneratedData(finalData);

        } catch (err) {
            console.error(err);
            const errorMessage = err instanceof Error ? err.message : 'Ancient engine failure.';
            setError(errorMessage);
        } finally {
            setIsLoading(false);
            setLoadingMessage('');
        }
    }, [imageSize, aspectRatio]);

    const handleStartOver = () => {
        setGeneratedData(null);
        setError(null);
        setUserInput('');
    }

    if (needsKey) {
        return (
            <div className="min-h-screen bg-[#0b0b0f] flex items-center justify-center p-6 text-center">
