import React, { useState, useMemo } from 'react';
import { analyzeLore } from '../services/geminiService';
import type { GeneratedData, PromptCard as PromptCardType } from '../types';

const Card: React.FC<{ card: PromptCardType; archetype: string; onImageClick: (src: string) => void }> = ({ card, archetype, onImageClick }) => {
  const [showPrompt, setShowPrompt] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [lore, setLore] = useState<string | null>(null);

  const handleCopy = async () => {
    try {
        await navigator.clipboard.writeText(card.prompt);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
    } catch (err) {
        console.error("Failed to copy", err);
    }
  };

  const handleAnalyze = async () => {
    if (isAnalyzing || lore) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeLore(card.title, card.caption);
      setLore(result);
    } catch (err) {
      setLore("The spirits refuse to speak.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <article className="card bg-[#111318] border border-[#242830] rounded-xl overflow-hidden flex flex-col group/card transition-all hover:border-[#c26b3a]/30">
      <div className="thumb aspect-video bg-[#0f1116] border-b border-[#242830] relative overflow-hidden">
        <img src={card.imageUrl} alt={card.title} className="w-full h-full object-cover block cursor-pointer transition-transform duration-700 group-hover/card:scale-110" onClick={() => onImageClick(card.imageUrl)} />
        <div className="absolute top-2 right-2 flex gap-1">
           <span className="bg-[#c26b3a] px-2 py-0.5 rounded text-[9px] font-black text-white uppercase shadow-lg">Nano Pro 4K</span>
        </div>
      </div>
      <div className="p-4 flex flex-col gap-3">
        <div className="flex justify-between items-start">
            <h3 className="font-bold text-lg text-[#e8e6e3]">{card.title}</h3>
            <button 
                onClick={handleAnalyze} 
                disabled={isAnalyzing}
                className={`text-[10px] font-bold tracking-tighter uppercase px-2 py-1 rounded border transition-all ${lore ? 'bg-transparent border-[#70757e] text-[#70757e]' : 'bg-[#f5a16f]/10 border-[#f5a16f]/30 text-[#f5a16f] hover:bg-[#f5a16f]/20'}`}
            >
                {isAnalyzing ? 'Decoding...' : lore ? 'Lore Intact' : '✧ Analyze'}
            </button>
        </div>

        {lore && (
            <div className="p-3 bg-black/40 border-l-2 border-[#f5a16f] rounded text-xs italic text-[#f0d7c2] leading-relaxed animate-fade-in">
                {lore}
            </div>
        )}

        <div className="meta flex gap-2 flex-wrap">
          <span className="chip bg-[#1b1f27] border border-[#242830] rounded-full px-3 py-1 text-[10px] font-bold text-[#70757e] uppercase">{archetype}</span>
          {card.tags.map(tag => <span key={tag} className="chip bg-[#1b1f27]/50 border border-[#242830] rounded-full px-3 py-1 text-[10px] font-bold text-[#f5a16f] uppercase">#{tag}</span>)}
        </div>

        <div className="actions flex gap-2 flex-wrap mt-2 no-print">
          <button onClick={() => setShowPrompt(!showPrompt)} className="btn flex-1 bg-transparent border border-[#242830] text-[#e8e6e3] px-4 py-2 rounded-lg text-sm font-semibold hover:bg-[#242830] transition-colors">
            {showPrompt ? 'Hide Logic' : 'View Logic'}
          </button>
          <button onClick={handleCopy} className="btn flex-1 bg-gradient-to-r from-[#8d1a1a] to-[#c26b3a] text-white px-4 py-2 rounded-lg text-sm font-bold hover:opacity-90 transition-opacity">
            {copied ? 'Copied!' : 'Copy Prompt'}
          </button>
        </div>

        <div className={`overflow-hidden transition-all duration-500 ${showPrompt ? 'max-h-96 opacity-100 mt-2' : 'max-h-0 opacity-0'}`}>
            <pre className="bg-[#0f1116] border border-[#242830] rounded-lg p-3 font-mono text-[10px] text-[#d9d5ce] whitespace-pre-wrap">{card.prompt}</pre>
        </div>
      </div>
    </article>
  );
};

