                <div className="p-8 rounded-3xl bg-[#111318] border border-[#242830] shadow-xl">
                    <h2 className="text-[10px] font-black text-[#f5a16f] uppercase tracking-[0.3em] mb-6">Manifestation Voids</h2>
                    <div className="flex flex-wrap gap-2">
