import React, { useState, useCallback } from 'react';
import { GeneratorForm } from './components/GeneratorForm';
import { LoadingScreen } from './components/LoadingScreen';
import { PromptCardSet } from './components/PromptCardSet';
import * as geminiService from './services/geminiService';
import type { GeneratedData } from './types';

const App: React.FC = () => {
    const [userInput, setUserInput] = useState<string>('');
    const [generatedData, setGeneratedData] = useState<GeneratedData | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

    // Default config for free tier
    const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '4:3'>('16:9');

    const handleGenerate = useCallback(async (idea: string) => {
        setIsLoading(true);
        setError(null);
        setGeneratedData(null);
        setUserInput(idea);

        try {
            setLoadingMessage('Consulting the Flash Engine...');
            const textData = await geminiService.generatePromptSet(idea);

            setLoadingMessage('Manifesting Cinematic Vectors...');

            const imagePrompts = [
                { type: 'banner', prompt: `Wide cinematic dark fantasy landscape, ${textData.tone}, gothic architecture, volumetric lighting, high contrast, 8k resolution.`, aspectRatio: aspectRatio },
                ...textData.cards.map((card, index) => ({
                    type: `card-${index}`,
                    prompt: `${card.title}, ${card.prompt.replace(/\n/g, ', ')}, dark fantasy horror, vivid colors, sharp focus`,
                    aspectRatio: aspectRatio
                }))
            ];

            const imageUrls: { [key:string]: string } = {};

            for (let i = 0; i < imagePrompts.length; i++) {
                const p = imagePrompts[i];
                setLoadingMessage(`Manifesting Relic ${i + 1}/${imagePrompts.length}...`);
                const imageUrl = await geminiService.generateImage(p.prompt, p.aspectRatio);
                imageUrls[p.type] = imageUrl;
            }

            const finalData: GeneratedData = {
                ...textData,
                mainTitle: 'The Demon Codex',
                bannerImageUrl: imageUrls['banner'],
                cards: textData.cards.map((card, index) => ({
                    ...card,
                    imageUrl: imageUrls[`card-${index}`] || '',
                })),
            };

            setGeneratedData(finalData);

        } catch (err) {
            console.error(err);
            setError(err instanceof Error ? err.message : 'Ancient engine failure.');
        } finally {
            setIsLoading(false);
            setLoadingMessage('');
        }
    }, [aspectRatio]);

    const handleStartOver = () => {
        setGeneratedData(null);
        setError(null);
        setUserInput('');
    }

    return (
        <div className="bg-[#0b0b0f] text-[#e8e6e3] font-['Inter'] min-h-screen w-full selection:bg-[#00d2ff] selection:text-black">
            <main className="max-w-[1100px] mx-auto p-4 md:p-5">
                {isLoading && <LoadingScreen message={loadingMessage} />}

                {!isLoading && !generatedData && (
                     <div className="flex flex-col items-center justify-center min-h-[80vh] py-12">
                        <div className="text-center mb-10 animate-fade-in">
                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#00d2ff]/10 border border-[#00d2ff]/30 text-[#00d2ff] text-xs font-bold tracking-widest uppercase mb-6 shadow-[0_0_15px_rgba(0,210,255,0.2)]">
                                <span className="w-2 h-2 rounded-full bg-[#00d2ff] animate-pulse shadow-[0_0_8px_#00d2ff]"></span>
                                Gemini Flash Tier
                            </div>

                            <div className="relative mb-6">
                                <h1 className="demon-title text-7xl md:text-[11rem] font-normal leading-none pointer-events-none drop-shadow-[0_10px_10px_rgba(0,0,0,1)]" data-text="The Demon Codex">
                                    The Demon Codex
                                </h1>
                            </div>

                            <p className="lightning-text text-lg md:text-xl mt-4 max-w-lg mx-auto leading-relaxed uppercase italic">
                                Forge high-fidelity dark fantasy relics and cinematic visual prompts.
                            </p>
                        </div>

                        <GeneratorForm
                            initialValue={userInput}
                            onGenerate={handleGenerate}
                            isGenerating={isLoading}
                            aspectRatio={aspectRatio}
                            setAspectRatio={setAspectRatio}
                        />

                         {error && (
                            <div className="mt-8 p-5 bg-[#8d1a1a]/20 border border-[#8d1a1a]/40 text-[#ff7b7b] rounded-xl max-w-xl text-center backdrop-blur-md shadow-2xl">
                                <p className="font-bold flex items-center justify-center gap-2 text-white"><span className="text-xl">⚠️</span> Forge Interrupted</p>
                                <p className="text-sm mt-1 opacity-90">{error}</p>
                            </div>
                        )}

                        <div className="mt-16 grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-2xl border-t border-[#242830] pt-12">
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830] hover:border-[#00d2ff]/30 transition-colors group">
                                <h3 className="text-white font-bold mb-2 group-hover:text-[#00d2ff]">Flash Engine</h3>
                                <p className="text-xs text-[#70757e]">Using Gemini 3 Flash for zero-cost intelligence and rapid worldbuilding.</p>
                            </div>
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830] hover:border-[#ff4d4d]/30 transition-colors group">
                                <h3 className="text-white font-bold mb-2 group-hover:text-[#ff4d4d]">Nano Manifest</h3>
                                <p className="text-xs text-[#70757e]">Cinematic imagery powered by Gemini 2.5 Flash native image capabilities.</p>
                            </div>
                        </div>
                    </div>
                )}

                {generatedData && (
                    <PromptCardSet data={generatedData} onStartOver={handleStartOver} />
                )}
            </main>
        </div>
    );
};

export default App;

