import React, { useState } from 'react';

interface GeneratorFormProps {
    initialValue: string;
    onGenerate: (idea: string) => void;
    isGenerating: boolean;
    aspectRatio: '1:1' | '16:9' | '4:3';
    setAspectRatio: (ratio: '1:1' | '16:9' | '4:3') => void;
}

const examples = [
    { label: 'Shattered Citadel', theme: 'Floating gothic cathedral pieces suspended in a vortex of red clouds' },
    { label: 'Eldritch Knight', theme: 'Heavy obsidian armor leaking cosmic smoke, standing in a field of glass flowers' },
    { label: 'The Sunken Altar', theme: 'Underwater marble altar glowing with bioluminescent tentacles' },
    { label: 'Ash Wasteland', theme: 'Infinite grey dunes with massive skeletal ribcages emerging from sand' },
];

export const GeneratorForm: React.FC<GeneratorFormProps> = ({ 
    initialValue, onGenerate, isGenerating, 
    aspectRatio, setAspectRatio 
}) => {
    const [idea, setIdea] = useState(initialValue);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (idea.trim() && !isGenerating) {
            onGenerate(idea.trim());
        }
    };

    return (
        <form onSubmit={handleSubmit} className="w-full max-w-3xl flex flex-col items-center gap-8">
            <div className="w-full flex flex-col gap-6">
                <textarea
                    value={idea}
                    onChange={(e) => setIdea(e.target.value)}
                    placeholder="Whisper your dark fantasy concept..."
                    className="w-full p-6 rounded-2xl border border-[#242830] focus:border-[#c26b3a] focus:ring-4 focus:ring-[#c26b3a]/10 transition-all bg-[#111318] shadow-2xl text-xl text-[#e8e6e3] placeholder:text-[#70757e] min-h-[140px] focus:outline-none"
                    disabled={isGenerating}
                />

                <div className="w-full max-w-sm mx-auto flex flex-col gap-2">
                    <label className="text-xs font-bold text-[#70757e] uppercase tracking-widest text-center">Composition</label>
                    <div className="flex bg-[#111318] p-1 rounded-xl border border-[#242830]">
                        {(['1:1', '16:9', '4:3'] as const).map((ratio) => (
                            <button
                                key={ratio}
                                type="button"
                                onClick={() => setAspectRatio(ratio)}
                                className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                                    aspectRatio === ratio 
                                    ? 'bg-[#c26b3a] text-white shadow-lg' 
                                    : 'text-[#70757e] hover:text-white'
                                }`}
                            >
                                {ratio}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            <div className="w-full">
                <div className="flex flex-wrap justify-center gap-3">
                    {examples.map(ex => (
                        <button 
                            key={ex.label}
                            type="button" 
                            onClick={() => !isGenerating && setIdea(ex.theme)} 
                            disabled={isGenerating}
                            className="bg-[#1b1f27]/50 border border-[#242830] rounded-full px-5 py-2 text-sm text-[#dcd8d3] hover:border-[#c26b3a] transition-all hover:scale-105 active:scale-95 disabled:opacity-50"
                        >
                            {ex.label}
                        </button>
                    ))}
                </div>
            </div>

            <button
                type="submit"
                disabled={isGenerating || !idea.trim()}
                className="group relative w-full md:w-auto overflow-hidden bg-gradient-to-r from-[#8d1a1a] to-[#c26b3a] text-white font-black text-xl py-5 px-16 rounded-2xl hover:opacity-90 transition-all duration-500 shadow-[0_0_30px_rgba(141,26,26,0.5)] active:scale-95 disabled:grayscale"
            >
                <span className="relative z-10">{isGenerating ? 'INITIATING...' : 'GENERATE RELICS'}</span>
                <div className="absolute inset-0 bg-white/10 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700 skew-x-[45deg]"></div>
            </button>
        </form>
    );
};

