const App: React.FC = () => {
    const [view, setView] = useState<'forge' | 'gallery'>('forge');
    const [userInput, setUserInput] = useState<string>('');
    const [generatedData, setGeneratedData] = useState<GeneratedData | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const [activeModal, setActiveModal] = useState<'privacy' | 'terms' | null>(null);

    const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '4:3'>('16:9');

    const handleGenerate = useCallback(async (idea: string) => {
        setIsLoading(true);
        setError(null);
        setGeneratedData(null);
        setUserInput(idea);

        try {
            setLoadingMessage('Consulting the Flash Engine...');
            const textData = await geminiService.generatePromptSet(idea);

            setLoadingMessage('Manifesting Cinematic Vectors...');

            const imagePrompts = [
                { type: 'banner', prompt: `Wide cinematic dark fantasy landscape, ${textData.tone}, gothic architecture, volumetric lighting, high contrast, 8k resolution.`, aspectRatio: aspectRatio },
                ...textData.cards.map((card, index) => ({
                    type: `card-${index}`,
                    prompt: `${card.title}, ${card.prompt.replace(/\n/g, ', ')}, dark fantasy horror, vivid colors, sharp focus`,
                    aspectRatio: aspectRatio
                }))
            ];

            const imageUrls: { [key:string]: string } = {};

            for (let i = 0; i < imagePrompts.length; i++) {
                const p = imagePrompts[i];
                setLoadingMessage(`Manifesting Relic ${i + 1}/${imagePrompts.length}...`);
                const imageUrl = await geminiService.generateImage(p.prompt, p.aspectRatio);
                imageUrls[p.type] = imageUrl;
            }

            const finalData: GeneratedData = {
                ...textData,
                mainTitle: 'The Demon Codex',
                bannerImageUrl: imageUrls['banner'],
                cards: textData.cards.map((card, index) => ({
                    ...card,
                    imageUrl: imageUrls[`card-${index}`] || '',
                })),
            };

            setGeneratedData(finalData);

        } catch (err) {
            console.error(err);
            setError(err instanceof Error ? err.message : 'Ancient engine failure.');
        } finally {
            setIsLoading(false);
            setLoadingMessage('');
        }
    }, [aspectRatio]);

    const handleStartOver = () => {
        setGeneratedData(null);
        setError(null);
        setUserInput('');
        setView('forge');
    }

    const openGallery = () => setView('gallery');

    return (
        <div className="bg-[#0b0b0f] text-[#e8e6e3] font-['Inter'] min-h-screen w-full selection:bg-[#00d2ff] selection:text-black flex flex-col">
