                    </div>
                )}

                {!isLoading && view === 'forge' && generatedData && (
                    <PromptCardSet data={generatedData} onStartOver={handleStartOver} onOpenGallery={openGallery} />
                )}
            </main>

            <footer className="w-full max-w-[1100px] mx-auto p-8 mt-auto border-t border-[#242830]/50 no-print">
                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex gap-4">
                        <button onClick={() => setActiveModal('privacy')} className="bg-[#111318] border border-[#242830] px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] text-[#70757e] hover:text-[#00d2ff] hover:border-[#00d2ff]/30 transition-all hover-blood">Privacy Policy</button>
