export const PromptCardSet: React.FC<{ data: GeneratedData, onStartOver: () => void, onOpenGallery: () => void }> = ({ data, onStartOver, onOpenGallery }) => {
    const [tagFilter, setTagFilter] = useState('');
    const [lightboxImage, setLightboxImage] = useState<string | null>(null);

    const allTags = useMemo(() => {
        const tags = data.cards.flatMap(c => c.tags);
        return [...new Set(tags)].sort();
    }, [data.cards]);

    const filteredCards = useMemo(() => {
        return data.cards.filter(card => !tagFilter || card.tags.includes(tagFilter));
    }, [data.cards, tagFilter]);

    return (
        <div className="w-full pb-12">
            <header className="relative h-[55vh] min-h-[450px] overflow-hidden rounded-[2.5rem] mb-12 shadow-[0_20px_60px_rgba(0,0,0,0.8)] group/banner border border-white/5">
                <img src={data.bannerImageUrl} alt="Series Banner" className="w-full h-full object-cover transition-transform duration-[3000ms] group-hover/banner:scale-110" />
                <div className="absolute inset-0 bg-gradient-to-t from-[#0b0b0f] via-[#0b0b0f]/30 to-transparent"></div>
                <div className="absolute bottom-0 inset-x-0 p-8 md:p-16">
                    <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#00d2ff]/20 border border-[#00d2ff]/40 text-[#00d2ff] text-[10px] font-black tracking-[0.2em] uppercase mb-4 shadow-[0_0_20px_rgba(0,210,255,0.3)]">
                        Flash Engine 8K
                    </div>
                    <h1 className="demon-title text-6xl md:text-[9rem] font-normal tracking-tighter leading-none mb-4 drop-shadow-[0_10px_10px_rgba(0,0,0,1)]" data-text={data.mainTitle}>
                        {data.mainTitle}
                    </h1>
                    <div className="flex items-center gap-4 text-lg md:text-2xl font-bold">
                        <span className="lightning-text uppercase italic">{data.archetype}</span>
                        <span className="w-1.5 h-1.5 rounded-full bg-[#00d2ff]/50"></span>
                        <span className="text-white/80 font-medium">{data.tone}</span>
                    </div>
                </div>
            </header>

            <div className="sticky top-6 z-[60] flex items-center gap-4 mb-10 p-3 rounded-2xl bg-[#111318]/90 backdrop-blur-2xl border border-[#242830] shadow-2xl no-print">
                <button onClick={onStartOver} className="bg-[#8d1a1a] hover:bg-[#ff4d4d] text-white px-6 py-3 rounded-xl text-xs font-black transition-all shadow-lg hover:shadow-[#ff4d4d]/20">↺ RESET FORGE</button>
                <div className="h-6 w-[1px] bg-[#242830]"></div>

                <button 
                    onClick={onOpenGallery}
                    className="bg-[#1b1f27] hover:bg-[#242830] text-[#00d2ff] px-6 py-3 rounded-xl text-xs font-black transition-all border border-[#00d2ff]/20 hover-blood flex items-center gap-2"
                >
                    <span className="text-lg">◈</span> ARCHIVE GALLERY
                </button>

                <div className="h-6 w-[1px] bg-[#242830]"></div>
                <select value={tagFilter} onChange={(e) => setTagFilter(e.target.value)} className="bg-transparent text-[#00d2ff] font-bold text-xs uppercase tracking-widest outline-none cursor-pointer">
                    <option value="" className="bg-[#111318]">All Archive Relics</option>
                    {allTags.map(tag => <option key={tag} value={tag} className="bg-[#111318]">{tag}</option>)}
                </select>
                <div className="flex-grow"></div>
                <button onClick={() => window.print()} className="px-6 py-3 rounded-xl border border-[#242830] text-xs font-bold hover:bg-[#00d2ff] hover:text-black hover:border-transparent transition-all">EXPORT PDF</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {filteredCards.map(card => <Card key={card.title} card={card} archetype={data.archetype} onImageClick={setLightboxImage} />)}
            </div>

            <section className="mt-16 grid grid-cols-1 md:grid-cols-2 gap-8 no-print">
                <div className="p-8 rounded-3xl bg-[#111318] border border-[#242830] shadow-xl hover:border-[#ff4d4d]/30 transition-colors group hover-blood">
                    <h2 className="text-[10px] font-black text-[#ff4d4d] uppercase tracking-[0.3em] mb-6">Manifestation Voids</h2>
                    <div className="flex flex-wrap gap-2">
                        {data.negativePrompts.map(p => <span key={p} className="text-[10px] px-3 py-1.5 bg-[#8d1a1a]/10 border border-[#8d1a1a]/20 text-[#ff7b7b] rounded-lg font-bold">{p}</span>)}
                    </div>
                </div>
                <div className="p-8 rounded-3xl bg-[#111318] border border-[#242830] shadow-xl hover:border-[#00d2ff]/30 transition-colors group hover-blood">
                    <h2 className="text-[10px] font-black text-[#00d2ff] uppercase tracking-[0.3em] mb-6">Remix Rituals</h2>
                    <ul className="space-y-4">
                        {data.remixSuggestions.map(s => <li key={s} className="text-xs text-[#9aa0a6] flex gap-3 leading-relaxed"><span className="text-[#00d2ff]">✦</span> {s}</li>)}
                    </ul>
                </div>
            </section>

            {lightboxImage && <Lightbox src={lightboxImage} onClose={() => setLightboxImage(null)} />}
        </div>
    );
};

