const App: React.FC = () => {
    const [view, setView] = useState<'forge' | 'gallery'>('forge');
    const [userInput, setUserInput] = useState<string>('');
    const [generatedData, setGeneratedData] = useState<GeneratedData | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const [activeModal, setActiveModal] = useState<'privacy' | 'terms' | null>(null);

    const [aspectRatio, setAspectRatio] = useState<'1:1' | '16:9' | '4:3'>('16:9');

    const handleGenerate = useCallback(async (idea: string) => {
        setIsLoading(true);
        setError(null);
        setGeneratedData(null);
        setUserInput(idea);

        try {
            setLoadingMessage('Consulting the Flash Engine...');
            const textData = await geminiService.generatePromptSet(idea);

            setLoadingMessage('Manifesting Cinematic Vectors...');

            const imagePrompts = [
                { type: 'banner', prompt: `Wide cinematic dark fantasy landscape, ${textData.tone}, gothic architecture, volumetric lighting, high contrast, 8k resolution.`, aspectRatio: aspectRatio },
                ...textData.cards.map((card, index) => ({
                    type: `card-${index}`,
                    prompt: `${card.title}, ${card.prompt.replace(/\n/g, ', ')}, dark fantasy horror, vivid colors, sharp focus`,
                    aspectRatio: aspectRatio
                }))
            ];

            const imageUrls: { [key:string]: string } = {};

            for (let i = 0; i < imagePrompts.length; i++) {
                const p = imagePrompts[i];
                setLoadingMessage(`Manifesting Relic ${i + 1}/${imagePrompts.length}...`);
                const imageUrl = await geminiService.generateImage(p.prompt, p.aspectRatio);
                imageUrls[p.type] = imageUrl;
            }

            const finalData: GeneratedData = {
                ...textData,
                mainTitle: 'The Demon Codex',
                bannerImageUrl: imageUrls['banner'],
                cards: textData.cards.map((card, index) => ({
                    ...card,
                    imageUrl: imageUrls[`card-${index}`] || '',
                })),
            };

            setGeneratedData(finalData);

        } catch (err) {
            console.error(err);
            setError(err instanceof Error ? err.message : 'Ancient engine failure.');
        } finally {
            setIsLoading(false);
            setLoadingMessage('');
        }
    }, [aspectRatio]);

    const handleStartOver = () => {
        setGeneratedData(null);
        setError(null);
        setUserInput('');
        setView('forge');
    }

    const openGallery = () => setView('gallery');

    return (
        <div className="bg-[#0b0b0f] text-[#e8e6e3] font-['Inter'] min-h-screen w-full selection:bg-[#00d2ff] selection:text-black flex flex-col">
            {/* Persistent Header */}
            <header className="fixed top-0 left-0 right-0 z-[100] px-6 py-4 flex justify-between items-center bg-gradient-to-b from-[#0b0b0f] via-[#0b0b0f]/80 to-transparent backdrop-blur-sm no-print">
                <div className="flex items-center gap-6">
                    <button onClick={handleStartOver} className="flex items-center gap-2 group">
                        <div className="w-8 h-8 rounded bg-[#8d1a1a] flex items-center justify-center shadow-[0_0_15px_#8d1a1a] group-hover:scale-110 transition-transform">
                             <span className="text-white font-black text-lg leading-none">D</span>
                        </div>
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-[#e8e6e3] hidden sm:block">Demon Codex</span>
                    </button>

                    <nav className="hidden md:flex gap-4">
                        <button 
                            onClick={openGallery}
                            className={`px-5 py-2 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center gap-2 border ${
                                view === 'gallery' 
                                ? 'bg-[#00d2ff] text-black border-[#00d2ff] shadow-[0_0_20px_rgba(0,210,255,0.4)]' 
                                : 'bg-[#111318]/80 border-[#242830] text-[#e8e6e3] hover:text-[#00d2ff] hover:border-[#00d2ff]/40 hover-blood'
                            }`}
                        >
                            <span className={view === 'gallery' ? 'text-black' : 'text-[#00d2ff]'}>◈</span> Relic Gallery
                        </button>
                    </nav>
                </div>

                <div className="flex gap-3">
                    <button className="px-5 py-2 rounded-lg bg-[#111318] border border-[#242830] text-sm font-bold text-[#e8e6e3] hover:text-white flex items-center gap-2">
                        <svg className="w-4 h-4" viewBox="0 0 24 24">
                            <path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
                            <path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
                            <path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
                            <path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.66l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
                        </svg>
                        Login
                    </button>
                    <button className="px-5 py-2 rounded-lg bg-[#8d1a1a] border border-transparent text-sm font-black text-white shadow-xl">
                        Sign Up
                    </button>
                </div>
            </header>

            <main className="flex-grow max-w-[1100px] mx-auto p-4 md:p-5 pt-28 w-full">
                {isLoading && <LoadingScreen message={loadingMessage} />}

                {!isLoading && view === 'gallery' && (
                    <Gallery onBack={() => setView('forge')} />
                )}

                {!isLoading && view === 'forge' && !generatedData && (
                     <div className="flex flex-col items-center justify-center min-h-[60vh] py-12">
                        <div className="text-center mb-10 animate-fade-in">
                            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#00d2ff]/10 border border-[#00d2ff]/30 text-[#00d2ff] text-xs font-bold tracking-widest uppercase mb-6 shadow-[0_0_15px_rgba(0,210,255,0.2)]">
                                <span className="w-2 h-2 rounded-full bg-[#00d2ff] animate-pulse shadow-[0_0_8px_#00d2ff]"></span>
                                Gemini Flash Tier
                            </div>

                            <div className="relative mb-6">
                                <h1 className="demon-title text-7xl md:text-[11rem] font-normal leading-none pointer-events-none drop-shadow-[0_10px_10px_rgba(0,0,0,1)]" data-text="The Demon Codex">
                                    The Demon Codex
                                    <BloodDrops />
                                </h1>
                            </div>

                            <p className="lightning-text text-lg md:text-xl mt-4 max-w-lg mx-auto leading-relaxed uppercase italic text-center">
                                Forge high-fidelity dark fantasy relics and cinematic visual prompts.
                            </p>
                        </div>

                        <GeneratorForm
                            initialValue={userInput}
                            onGenerate={handleGenerate}
                            isGenerating={isLoading}
                            aspectRatio={aspectRatio}
                            setAspectRatio={setAspectRatio}
                        />

                         {error && (
                            <div className="mt-8 p-5 bg-[#8d1a1a]/20 border border-[#8d1a1a]/40 text-[#ff7b7b] rounded-xl max-w-xl text-center backdrop-blur-md shadow-2xl">
                                <p className="font-bold flex items-center justify-center gap-2 text-white"><span className="text-xl">⚠️</span> Forge Interrupted</p>
                                <p className="text-sm mt-1 opacity-90">{error}</p>
                            </div>
                        )}

                        <div className="mt-16 grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-2xl border-t border-[#242830] pt-12">
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830] hover:border-[#00d2ff]/30 transition-colors group cursor-pointer hover-blood">
                                <h3 className="text-white font-bold mb-2 group-hover:text-[#00d2ff]">Flash Engine</h3>
                                <p className="text-xs text-[#70757e]">Using Gemini 3 Flash for zero-cost intelligence and rapid worldbuilding.</p>
                            </div>
                            <div className="p-6 rounded-2xl bg-[#111318]/50 border border-[#242830] hover:border-[#ff4d4d]/30 transition-colors group cursor-pointer hover-blood">
                                <h3 className="text-white font-bold mb-2 group-hover:text-[#ff4d4d]">Nano Manifest</h3>
                                <p className="text-xs text-[#70757e]">Cinematic imagery powered by Gemini 2.5 Flash native image capabilities.</p>
                            </div>
                        </div>
                    </div>
                )}

                {!isLoading && view === 'forge' && generatedData && (
                    <PromptCardSet data={generatedData} onStartOver={handleStartOver} onOpenGallery={openGallery} />
                )}
            </main>

            <footer className="w-full max-w-[1100px] mx-auto p-8 mt-auto border-t border-[#242830]/50 no-print">
                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex gap-4">
                        <button onClick={() => setActiveModal('privacy')} className="bg-[#111318] border border-[#242830] px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] text-[#70757e] hover:text-[#00d2ff] hover:border-[#00d2ff]/30 transition-all hover-blood">Privacy Policy</button>
                        <button onClick={() => setActiveModal('terms')} className="bg-[#111318] border border-[#242830] px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-[0.2em] text-[#70757e] hover:text-[#00d2ff] hover:border-[#00d2ff]/30 transition-all hover-blood">Terms of Service</button>
                    </div>
                    <div className="flex items-center gap-2 text-[10px] font-bold text-[#444] tracking-widest uppercase">
                        <span className="w-2 h-2 rounded-full bg-[#8d1a1a]"></span>
                        &copy; 2024 The Demon Codex — All Relics Reserved
                    </div>
                </div>
            </footer>

            <LegalModal 
                title="Privacy Policy"
                isOpen={activeModal === 'privacy'}
                onClose={() => setActiveModal(null)}
                content={
                    <>
                        <p>At <strong className="text-white">The Demon Codex</strong>, we respect the sanctity of your digital shadow. We only process data required to manifest your creative visions through the Google Gemini API.</p>
                        <p>1. <strong className="text-[#00d2ff]">Manifestation Data:</strong> We do not store your prompts or the resulting relics permanently. All generation occurs in real-time flux.</p>
                        <p>2. <strong className="text-[#00d2ff]">Google Auth:</strong> When you login with Google, we only receive your unique identifier to manage your creative sessions.</p>
                        <p>3. <strong className="text-[#00d2ff]">Security:</strong> All transmissions are encrypted with abyssal-grade protocols.</p>
                    </>
                }
            />
            <LegalModal 
                title="Terms of Service"
                isOpen={activeModal === 'terms'}
                onClose={() => setActiveModal(null)}
                content={
                    <>
                        <p>By entering <strong className="text-white">The Demon Codex</strong>, you agree to the following ethereal compact:</p>
                        <p>1. <strong className="text-[#00d2ff]">Permitted Use:</strong> You may use these relics for personal or commercial storytelling with credit.</p>
                        <p>2. <strong className="text-[#00d2ff]">Prohibitions:</strong> You shall not manifest forbidden symbols or real-world malice.</p>
                        <p>3. <strong className="text-[#00d2ff]">Hallucinations:</strong> The forge may occasionally produce artifacts of chaos.</p>
                    </>
                }
            />
        </div>
    );
};

