import { GoogleGenAI, Type } from "@google/genai";
import type { GeneratedData, PromptCard } from '../types';

const FAILED_IMAGE_PLACEHOLDER = 'data:image/svg+xml;base64,';

const responseSchema = {
  type: Type.OBJECT,
  properties: {
    archetype: { type: Type.STRING, description: "A single, powerful archetype (e.g., Void-Stalker, Blood-Paladin)." },
    tone: { type: Type.STRING, description: "Descriptive words for the atmosphere (e.g., Abyssal, Melancholic)." },
    use: { type: Type.STRING, description: "Intended cinematic use case." },
    cards: {
      type: Type.ARRAY,
      description: "Exactly 5 unique Relic cards.",
      items: {
        type: Type.OBJECT,
        properties: {
          glyph: { type: Type.STRING, description: "A thematic emoji." },
          title: { type: Type.STRING, description: "Evocative relic name." },
          prompt: { type: Type.STRING, description: "Multi-line technical prompt for Subject, Lighting, Style, etc." },
          caption: { type: Type.STRING, description: "Brief visual description." },
          tags: { type: Type.ARRAY, items: { type: Type.STRING }, description: "2-4 category tags." },
        },
        required: ["glyph", "title", "prompt", "caption", "tags"],
      },
    },
    negativePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
    remixSuggestions: { type: Type.ARRAY, items: { type: Type.STRING } },
  },
  required: ["archetype", "tone", "use", "cards", "negativePrompts", "remixSuggestions"],
};

export const generatePromptSet = async (idea: string): Promise<Omit<GeneratedData, 'mainTitle' | 'bannerImageUrl' | 'cards'> & { cards: Omit<PromptCard, 'imageUrl'>[] }> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Create a dark fantasy Relic Series based on: "${idea}". Output valid JSON matching the required schema.`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: responseSchema,
        }
    });

    return JSON.parse(response.text?.trim() || "{}");
};

export const generateImage = async (
    prompt: string, 
    aspectRatio: '1:1' | '16:9' | '4:3' | '9:16' | '3:4' = '16:9'
): Promise<string> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ text: `Dark fantasy masterpiece: ${prompt}` }] },
            config: {
                imageConfig: { aspectRatio }
            },
        });

        if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData?.data) {
                    return `data:image/png;base64,${part.inlineData.data}`;
                }
            }
        }
        return FAILED_IMAGE_PLACEHOLDER;
    } catch (error: any) {
        console.error("Image gen error:", error);
        return FAILED_IMAGE_PLACEHOLDER;
    }
};

export const generateRelicVideo = async (
    base64Image: string, 
    title: string, 
    duration: 5 | 10 = 5,
    aspectRatio: '16:9' | '9:16' = '16:9'
): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const base64Data = base64Image.split(',')[1] || base64Image;

    // Note: Veo 3.1-fast supports 5s/10s logic via prompt or resolution/config
    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: `Cinematic subtle movement, atmospheric smoke drifting, embers falling in a dark fantasy style, highly detailed, matching the relic: ${title}. ${duration} seconds of ethereal motion.`,
      image: {
        imageBytes: base64Data,
        mimeType: 'image/png',
      },
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: aspectRatio
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000));
      operation = await ai.operations.getVideosOperation({operation: operation});
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("Video manifestation failed.");

    return `${downloadLink}&key=${process.env.API_KEY}`;
};

export const analyzeLore = async (title: string, caption: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this relic: "${title}". Description: "${caption}". Write a 2-sentence mysterious lore snippet.`,
    });
    return response.text || "Lore lost to time.";
};

import React, { useState, useMemo } from 'react';
import { analyzeLore, generateRelicVideo } from '../services/geminiService';
import type { GeneratedData, PromptCard as PromptCardType } from '../types';

const Card: React.FC<{ card: PromptCardType; archetype: string; onImageClick: (src: string) => void }> = ({ card, archetype, onImageClick }) => {
  const [showPrompt, setShowPrompt] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [lore, setLore] = useState<string | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isAnimating, setIsAnimating] = useState(false);

  // Video Options
  const [videoDuration, setVideoDuration] = useState<5 | 10>(5);
  const [videoRatio, setVideoRatio] = useState<'16:9' | '9:16'>('16:9');
  const [showVideoConfig, setShowVideoConfig] = useState(false);

  const handleCopy = async () => {
    try {
        await navigator.clipboard.writeText(card.prompt);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
    } catch (err) {
        console.error("Failed to copy", err);
    }
  };

  const handleAnalyze = async () => {
    if (isAnalyzing || lore) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeLore(card.title, card.caption);
      setLore(result);
    } catch (err) {
      setLore("The spirits refuse to speak.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAnimate = async () => {
    if (isAnimating || videoUrl) return;
    setIsAnimating(true);
    setShowVideoConfig(false);
    try {
      const url = await generateRelicVideo(card.imageUrl, card.title, videoDuration, videoRatio);
      setVideoUrl(url);
    } catch (err) {
      console.error("Video ritual failed", err);
    } finally {
      setIsAnimating(false);
    }
